CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS atmospheric_datasets(id INTEGER PRIMARY KEY, project_id INTEGER REFERENCES projects(id), name TEXT NOT NULL, original_filename TEXT, stored_path TEXT, file_sha256 TEXT, content_sha256 TEXT, source TEXT, model TEXT, description TEXT, mapping_json TEXT, metadata_json TEXT, n_rows INTEGER, version INTEGER DEFAULT 1, uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_ds_file ON atmospheric_datasets(file_sha256);
CREATE TABLE IF NOT EXISTS dataset_versions(id INTEGER PRIMARY KEY, dataset_id INTEGER REFERENCES atmospheric_datasets(id) ON DELETE CASCADE, version INTEGER, snapshot_json TEXT, changed_at TEXT DEFAULT CURRENT_TIMESTAMP);
-- Profiles are stored in SI: m, K, kg/m^3, m^-3
CREATE TABLE IF NOT EXISTS atmospheric_profiles(id INTEGER PRIMARY KEY, dataset_id INTEGER REFERENCES atmospheric_datasets(id) ON DELETE CASCADE, altitude_m REAL NOT NULL, temperature_k REAL, total_density_kg_m3 REAL);
CREATE TABLE IF NOT EXISTS atmospheric_species(id INTEGER PRIMARY KEY, dataset_id INTEGER REFERENCES atmospheric_datasets(id) ON DELETE CASCADE, profile_id INTEGER REFERENCES atmospheric_profiles(id) ON DELETE CASCADE, species TEXT NOT NULL, number_density_m3 REAL NOT NULL);
CREATE TABLE IF NOT EXISTS spacecraft_configurations(id INTEGER PRIMARY KEY, project_id INTEGER REFERENCES projects(id), name TEXT, params_json TEXT, version INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS geometry_files(id INTEGER PRIMARY KEY, config_id INTEGER REFERENCES spacecraft_configurations(id), filename TEXT, stored_path TEXT, sha256 TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS geometry_versions(id INTEGER PRIMARY KEY, config_id INTEGER REFERENCES spacecraft_configurations(id), version INTEGER, snapshot_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fmf_configurations(id INTEGER PRIMARY KEY, project_id INTEGER, name TEXT, params_json TEXT, dataset_id INTEGER REFERENCES atmospheric_datasets(id), spacecraft_id INTEGER REFERENCES spacecraft_configurations(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fmf_results(id INTEGER PRIMARY KEY, fmf_id INTEGER REFERENCES fmf_configurations(id), results_json TEXT, model_version TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dsmc_configurations(id INTEGER PRIMARY KEY, project_id INTEGER, name TEXT, params_json TEXT, solver TEXT DEFAULT 'SPARTA', solver_version TEXT, dataset_id INTEGER REFERENCES atmospheric_datasets(id), spacecraft_id INTEGER REFERENCES spacecraft_configurations(id), version INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dsmc_jobs(id INTEGER PRIMARY KEY, dsmc_id INTEGER REFERENCES dsmc_configurations(id), status TEXT DEFAULT 'draft' CHECK(status IN ('draft','validating','ready','running','completed','failed')), input_path TEXT, log_path TEXT, meta_json TEXT, started_at TEXT, finished_at TEXT);
CREATE TABLE IF NOT EXISTS dsmc_results(id INTEGER PRIMARY KEY, job_id INTEGER REFERENCES dsmc_jobs(id), output_path TEXT, imported INTEGER DEFAULT 0, summary_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS simulation_comparisons(id INTEGER PRIMARY KEY, project_id INTEGER, name TEXT, inputs_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY, project_id INTEGER, kind TEXT, path TEXT, meta_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scientific_references(id INTEGER PRIMARY KEY, key TEXT UNIQUE, citation TEXT, doi TEXT);
CREATE TABLE IF NOT EXISTS activity_log(id INTEGER PRIMARY KEY, kind TEXT, message TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
